"""Rename Drive files to the naming convention (plan Task 11; README Naming). IDs and links do not change.

Input: a CSV with columns folder,old,new (folder path as in the index, from 'My Drive'). Dry run by default:
resolves each row to one file id in the index and prints old -> new. --apply checks the live name is still `old`
and the file is not shared, renames, and logs id,old,new,status to drive-index/rename_log.csv (undo: rename new
back to old). Safe to rerun: ids already logged `renamed` are skipped without an API call.
Statuses: renamed | skip_changed (live name differs or trashed) | skip_shared | no_read (gws read failed, retry) | error.
Usage: python3 -I rename.py drive-index/rename_<batch>.csv [--apply] [--threads 12]
"""
import argparse, csv, json, sqlite3, subprocess, threading
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

OUT = Path.home() / "DEV/drive-tools/drive-index"
BAD = set("'’()+ ")   # convention: no spaces, apostrophes, parentheses


def gws(args):
    r = subprocess.run(["gws", "drive", "files", *args], capture_output=True, text=True)
    try:
        return json.loads(r.stdout)
    except ValueError:
        return None


def resolve(rows):
    con = sqlite3.connect(f"file:{OUT / 'drive.sqlite'}?mode=ro", uri=True)
    out = []
    for r in rows:
        ids = con.execute("select id from files where folder=? and name=?", (r["folder"], r["old"])).fetchall()
        if len(ids) != 1:
            out.append((None, r, f"skip: {len(ids)} matches"))
        elif BAD & set(r["new"]) or "/" in r["new"]:
            out.append((None, r, "skip: new name breaks the convention"))
        else:
            out.append((ids[0][0], r, "ok"))
    return out


def done_ids(path):
    """Ids whose last logged status is `renamed` (a later undo row would not be `renamed`)."""
    last = {}
    if path.exists():
        for row in csv.reader(open(path)):
            if len(row) >= 4:
                last[row[0]] = row[-1]
    return {i for i, s in last.items() if s == "renamed"}


def live_status(m, old):
    if m is None:
        return "no_read"
    if m.get("trashed") or m.get("name") != old:
        return "skip_changed"
    if m.get("shared"):
        return "skip_shared"
    return "ok"


def apply_one(fid, r):
    m = gws(["get", "--params", json.dumps({"fileId": fid, "fields": "name,trashed,shared"})])
    s = live_status(m, r["old"])
    if s != "ok":
        return s
    u = gws(["update", "--params", json.dumps({"fileId": fid, "fields": "name"}), "--json", json.dumps({"name": r["new"]})])
    return "renamed" if u and u.get("name") == r["new"] else "error"


def selftest():
    assert live_status(None, "a") == "no_read"
    assert live_status({"name": "b"}, "a") == "skip_changed"
    assert live_status({"name": "a", "trashed": True}, "a") == "skip_changed"
    assert live_status({"name": "a", "shared": True}, "a") == "skip_shared"
    assert live_status({"name": "a", "shared": False}, "a") == "ok"
    print("selftest ok")


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("csv", nargs="?")
    ap.add_argument("--apply", action="store_true")
    ap.add_argument("--threads", type=int, default=1, help="parallel workers; 12 is the useful ceiling")
    ap.add_argument("--selftest", action="store_true")
    a = ap.parse_args()
    if a.selftest or not a.csv:
        return selftest()
    plan = resolve(list(csv.DictReader(open(a.csv))))
    done = done_ids(OUT / "rename_log.csv") if a.apply else set()
    fh = open(OUT / "rename_log.csv", "a", newline="") if a.apply else None
    log, lock, counts = (csv.writer(fh) if fh else None), threading.Lock(), {}

    def work(item):
        fid, r, why = item
        status = why
        if fid and fid in done:
            status = "already_renamed"
        elif fid and a.apply:
            status = apply_one(fid, r)
        with lock:
            if fid and a.apply and status != "already_renamed":
                log.writerow([fid, r["old"], r["new"], status])
                fh.flush()
            if status != "already_renamed":
                print(f"{status:12} {r['old']}  ->  {r['new']}", flush=True)
            k = status.split(":")[0]
            counts[k] = counts.get(k, 0) + 1

    with ThreadPoolExecutor(max(1, a.threads)) as ex:
        list(ex.map(work, plan))
    print(counts)


if __name__ == "__main__":
    main()

